<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { ArrowDownToLine, ArrowRight, BadgeCheck, Boxes, CircleAlert, LoaderCircle, Package, Pencil, Plus, Search, SlidersHorizontal, Sparkles, TrendingUp, X } from '@lucide/vue';
import { discardQueuedOperation, download, get, list, patch, post, queueOfflineAction, remove, retryQueuedOperation, synchronizeOfflineQueue } from '../api/http';
import { useSession } from '../stores/session';
import { useI18n } from '../i18n';
import { isOnline, listQueuedOperations, type OfflineOperation } from '../offline';

interface Row { id:string; [key:string]:any }
interface Product extends Row { sku:string; name:string; brand:string; unit:string; stock_quantity:string; min_stock:string; selling_price:string; cost_price?:string; category:number|null; is_active:boolean }
interface Supplier extends Row { name:string; phone:string; email:string; address:string; notes:string; is_active:boolean }
const route=useRoute(); const session=useSession(); const {t,locale}=useI18n();
const section=computed(()=>String(route.meta.section||''));
const rows=ref<Row[]>([]); const products=ref<Product[]>([]); const suppliers=ref<Supplier[]>([]); const categories=ref<Row[]>([]);
const busy=ref(false); const pending=ref(false); const error=ref(''); const success=ref(''); const search=ref(''); const modal=ref(false); const action=ref(''); const editing=ref<Row|null>(null); const form=ref<Record<string,any>>({});
const dateFrom=ref(new Date(Date.now()-29*86400000).toISOString().slice(0,10)); const dateTo=ref(new Date().toISOString().slice(0,10));
const report=ref<any>(null); const lowStock=ref<any[]>([]);
const queuedOperations=ref<OfflineOperation[]>([]);
const role=session.role;
const config=computed(()=>({
 categories:{endpoint:'categories/',title:t('Catégories de produits'),sub:t('Organisez votre catalogue en familles faciles à parcourir.'),label:t('Nouvelle catégorie'),icon:Boxes,search:t('Rechercher une catégorie'),add:['owner','manager','stock_manager'].includes(role)},
 products:{endpoint:'products/',title:t('Catalogue produits'),sub:t('Tous vos produits, prix et seuils de réapprovisionnement.'),label:t('Produit'),icon:Package,search:t('Nom, référence ou marque'),add:['owner','manager','stock_manager'].includes(role)},
 stock:{endpoint:'stock/movements/',title:t('Mouvements de stock'),sub:t('Un historique clair de chaque entrée, sortie et ajustement.'),label:t('Ajustement'),icon:Boxes,search:t('Filtrer par produit ou référence'),add:['owner','manager','stock_manager'].includes(role)},
 sales:{endpoint:'sales/',title:t('Ventes & caisse'),sub:t('Retrouvez les tickets et démarrez une nouvelle vente.'),label:t('Nouvelle vente'),icon:TrendingUp,search:t('Rechercher un ticket'),add:['owner','manager','seller'].includes(role)},
 purchases:{endpoint:'purchases/',title:t('Achats'),sub:t('Suivez les commandes, réceptions et approvisionnements.'),label:t('Nouvel achat'),icon:ArrowDownToLine,search:t('Référence ou fournisseur'),add:['owner','manager','stock_manager'].includes(role)},
 suppliers:{endpoint:'suppliers/',title:t('Fournisseurs'),sub:t('Vos partenaires et leurs coordonnées au même endroit.'),label:t('Ajouter un fournisseur'),icon:Boxes,search:t('Nom ou téléphone'),add:['owner','manager','stock_manager'].includes(role)},
 team:{endpoint:'members/',title:t('Votre équipe'),sub:t('Les accès et rôles de chaque personne de ce commerce.'),label:t('Inviter un membre'),icon:BadgeCheck,search:t('Nom ou e-mail'),add:role==='owner'},
 reports:{endpoint:'reports/sales/',title:t('Rapports & activité'),sub:t('Les chiffres utiles pour décider du prochain pas.'),label:t('Exporter les ventes'),icon:TrendingUp,search:'',add:true},
}[section.value]||{endpoint:'',title:t('Gestion'),sub:'',label:t('Ajouter'),icon:Package,search:'',add:false}));
const title=computed(()=>config.value.title); const canAdd=computed(()=>config.value.add&&(isOnline.value||['sales','stock','purchases'].includes(section.value))); const canManage=computed(()=>isOnline.value&&['owner','manager','stock_manager'].includes(role)); const currency=computed(()=>session.shop?.currency||'XOF');
const visibleQueuedOperations=computed(()=>queuedOperations.value.filter(operation=>operation.userId===session.user?.id&&operation.shopId===session.activeShopId&&(operation.state!=='done'||(!isOnline.value&&operation.kind==='purchase_create'&&operation.retainForDependency))));
const filteredRows=computed(()=>{ const term=search.value.trim().toLocaleLowerCase(); if(!term)return rows.value; return rows.value.filter(row=>Object.values(row).some(value=>String(value??'').toLocaleLowerCase().includes(term))); });
function money(v:any){return new Intl.NumberFormat(locale.value,{style:'currency',currency:currency.value,maximumFractionDigits:0}).format(Number(v||0));}
function fmtDate(v:any){if(!v)return '—';return new Intl.DateTimeFormat(locale.value,{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v));}
function num(v:any){return Number(v||0).toLocaleString(locale.value,{maximumFractionDigits:3});}
function unitName(u:string){return t(({piece:'pièce',box:'boîte',pack:'paquet',meter:'mètre',roll:'rouleau',liter:'litre',kg:'kg'} as Record<string,string>)[u]||u);}
function statusName(s:string){return t(({completed:'Terminée',cancelled:'Annulée',draft:'Brouillon',ordered:'Commandé',received:'Réceptionné',owner:'Propriétaire',manager:'Gérant·e',stock_manager:'Gestion de stock',seller:'Vendeur·se',viewer:'Lecture seule'} as Record<string,string>)[s]||s);}
function statusClass(s:string){return s==='completed'||s==='received'?'status-green':s==='cancelled'?'status-red':s==='ordered'?'status-blue':'status-amber';}
async function load(){if(!session.activeShopId)return;busy.value=true;error.value='';success.value='';try{
 if(section.value==='reports'){
   const [r,l]=await Promise.all([get<any>('reports/sales/',{date_from:dateFrom.value,date_to:dateTo.value}),list<any>('reports/low-stock/')]);report.value=r;lowStock.value=l;rows.value=r.top_products||[];
 }else{
   rows.value=await list<Row>(config.value.endpoint,section.value==='sales'?{ordering:'-created_at'}:{});
   if(section.value==='products') { products.value=rows.value as Product[]; categories.value=await list<Row>('categories/'); }
   if(section.value==='categories') categories.value=rows.value;
   if(section.value==='sales'||section.value==='purchases'||section.value==='stock') products.value=await list<Product>('products/');
   if(section.value==='purchases') suppliers.value=await list<Supplier>('suppliers/');
 }
 }catch(e){error.value=e instanceof Error?e.message:'Impossible de charger ces données.';}finally{busy.value=false;}}
async function refreshQueue(){try{queuedOperations.value=await listQueuedOperations();}catch(e){error.value=e instanceof Error?e.message:'Impossible de lire la file de synchronisation.';}}
onMounted(()=>{load();refreshQueue();window.addEventListener('online',refreshQueue);window.addEventListener('offline',refreshQueue);});
onMounted(()=>window.addEventListener('kawa:offline-queue-updated',refreshQueue));
onUnmounted(()=>{window.removeEventListener('online',refreshQueue);window.removeEventListener('offline',refreshQueue);window.removeEventListener('kawa:offline-queue-updated',refreshQueue);});
watch(()=>[section.value,session.activeShopId] as const,()=>{load();refreshQueue();});
watch([dateFrom,dateTo],()=>{if(section.value==='reports')load();});
function openCreate(){if(section.value==='reports'){download('reports/sales/export/?date_from='+dateFrom.value+'&date_to='+dateTo.value,'ventes-kawastock.csv').catch(e=>error.value=e.message);return;}
 action.value=section.value; editing.value=null; error.value=''; success.value='';
 if(section.value==='products')form.value={sku:'',name:'',brand:'',barcode:'',unit:'piece',category:'',cost_price:'0',selling_price:'0',min_stock:session.shop?.default_min_stock||'0',is_active:true};
 if(section.value==='categories')form.value={name:'',parent:''};
 if(section.value==='suppliers')form.value={name:'',phone:'',email:'',address:'',notes:''};
 if(section.value==='stock')form.value={product_id:'',quantity_delta:'',movement_type:'adjustment',reason:''};
 if(section.value==='sales')form.value={items:[{product_id:'',quantity:'1'}],discount_amount:'0'};
 if(section.value==='purchases')form.value={supplier_id:'',product_id:'',quantity_ordered:'1',unit_cost:'0',notes:''};
 if(section.value==='team')form.value={email:'',username:'',password:'',role:'seller'};
 modal.value=true;
}
async function save(){pending.value=true;error.value='';let queuedResult:OfflineOperation|null=null;try{
 if(action.value==='products') { const payload={...form.value,category:form.value.category||null}; if(editing.value) await patch(`products/${editing.value.id}/`,payload); else await post('products/',payload); }
 else if(action.value==='categories') { const payload={...form.value,parent:form.value.parent||null}; if(editing.value) await patch(`categories/${editing.value.id}/`,payload); else await post('categories/',payload); }
 else if(action.value==='suppliers') { if(editing.value) await patch(`suppliers/${editing.value.id}/`,form.value); else await post('suppliers/',form.value); }
 else if(action.value==='stock') queuedResult=await queueOfflineAction('stock_adjustment',form.value);
 else if(action.value==='sales') queuedResult=await queueOfflineAction('sale',{items:form.value.items.filter((item:any)=>item.product_id&&Number(item.quantity)>0).map((item:any)=>({product_id:item.product_id,quantity:item.quantity})),discount_amount:form.value.discount_amount||'0'});
 else if(action.value==='purchases') queuedResult=await queueOfflineAction('purchase_create',{supplier_id:form.value.supplier_id,items:[{product_id:form.value.product_id,quantity_ordered:form.value.quantity_ordered,unit_cost:form.value.unit_cost}],notes:form.value.notes||''});
 else if(action.value==='team') await post('members/',form.value);
 if(queuedResult?.state==='conflict')throw new Error(queuedResult.error||'Conflit à résoudre');
 const savedSection=action.value; modal.value=false; await refreshQueue(); success.value=queuedResult?.state==='pending'?'Opération enregistrée sur cet appareil; synchronisation en attente.':savedSection==='sales'?'Vente enregistrée.':savedSection==='stock'?'Mouvement de stock ajouté.':savedSection==='purchases'?'Achat enregistré.':'Enregistrement effectué.'; await load();
 }catch(e){error.value=e instanceof Error?e.message:'Enregistrement impossible.';}finally{pending.value=false;}}
async function cancelSale(row:Row){const reason=window.prompt(t('Motif obligatoire (3 caractères minimum) pour annuler cette vente :'));if(!reason||reason.trim().length<3)return;error.value='';try{await post(`sales/${row.id}/cancel/`,{reason:reason.trim()});success.value='La vente a été annulée et le stock rétabli.';await load();}catch(e){error.value=e instanceof Error?e.message:'Annulation impossible.';}}
async function receivePurchase(row:Row){if(!window.confirm(`${t('Réceptionner l’achat')} ${row.reference} ? ${t('Le stock sera mis à jour.')}`))return;try{const queued=await queueOfflineAction('purchase_receive',{purchaseId:String(row.id)});if(queued.state==='conflict')throw new Error(queued.error||'Réception impossible.');success.value=queued.state==='pending'?'Réception enregistrée; synchronisation en attente.':`${row.reference} ${t('Réceptionné').toLowerCase()}.`;await refreshQueue();await load();}catch(e){error.value=e instanceof Error?e.message:'Réception impossible.';}}
async function receiveQueuedPurchase(operation:OfflineOperation){try{await queueOfflineAction('purchase_receive',{purchaseId:`local:${operation.id}`},operation.id);await refreshQueue();}catch(e){error.value=e instanceof Error?e.message:'Réception impossible.';}}
async function retryOperation(operation:OfflineOperation){try{await retryQueuedOperation(operation.id);await refreshQueue();await load();}catch(e){error.value=e instanceof Error?e.message:'Synchronisation impossible.';}}
async function discardOperation(operation:OfflineOperation){try{if(operation.kind==='purchase_create'){const operations=await listQueuedOperations();for(const dependent of operations.filter(item=>item.dependsOn===operation.id))await discardQueuedOperation(dependent.id);}await discardQueuedOperation(operation.id);await refreshQueue();}catch(e){error.value=e instanceof Error?e.message:'Impossible de retirer cette opération.';}}
function operationLabel(operation:OfflineOperation){if(operation.state==='done')return t('Commande d’achat synchronisée');return t(({sale:'Vente en attente',stock_adjustment:'Ajustement de stock en attente',purchase_create:'Commande d’achat en attente',purchase_receive:'Réception en attente'} as Record<string,string>)[operation.kind]);}
async function syncQueue(){try{await synchronizeOfflineQueue();await refreshQueue();await load();}catch(e){error.value=e instanceof Error?e.message:'Synchronisation impossible.';}}
async function cancelPurchase(row:Row){if(!window.confirm(`${t('Annuler')} ${row.reference} ?`))return;try{await post(`purchases/${row.id}/cancel/`,{});success.value=`${row.reference} ${t('Annulée').toLowerCase()}.`;await load();}catch(e){error.value=e instanceof Error?e.message:'Annulation impossible.';}}
async function toggleMember(row:Row){try{await patch(`members/${row.id}/`,{is_active:!row.is_active});success.value='Accès mis à jour.';await load();}catch(e){error.value=e instanceof Error?e.message:'Modification impossible.';}}
function editProduct(row:Row){action.value='products';editing.value=row;form.value={sku:row.sku,name:row.name,brand:row.brand||'',barcode:row.barcode||'',unit:row.unit,category:row.category??'',cost_price:row.cost_price??'0',selling_price:row.selling_price,min_stock:row.min_stock,is_active:row.is_active};modal.value=true;}
function editCategory(row:Row){action.value='categories';editing.value=row;form.value={name:row.name,parent:row.parent??''};modal.value=true;}
function editSupplier(row:Row){action.value='suppliers';editing.value=row;form.value={name:row.name,phone:row.phone||'',email:row.email||'',address:row.address||'',notes:row.notes||''};modal.value=true;}
async function toggleProduct(row:Row){try{await patch(`products/${row.id}/`,{is_active:!row.is_active});success.value=row.is_active?'Produit désactivé.':'Produit réactivé.';await load();}catch(e){error.value=e instanceof Error?e.message:'Modification impossible.';}}
async function deactivateSupplier(row:Row){if(!window.confirm(`${t('Désactiver le fournisseur')} ${row.name} ?`))return;try{await remove(`suppliers/${row.id}/`);success.value='Fournisseur désactivé.';await load();}catch(e){error.value=e instanceof Error?e.message:'Modification impossible.';}}
function productFor(id:string){return products.value.find(p=>p.id===id);}
function addSaleItem(){form.value.items.push({product_id:'',quantity:'1'});}
function removeSaleItem(index:number|string){if(form.value.items.length>1)form.value.items.splice(Number(index),1);}
const estimatedSaleTotal=computed(()=>Math.max(0,(form.value.items||[]).reduce((total:number,item:any)=>total+Number(productFor(item.product_id)?.selling_price||0)*Number(item.quantity||0),0)-Number(form.value.discount_amount||0)));
</script>

<template>
  <div class="page-heading"><div><span class="eyebrow">{{ t(session.shop?.name || 'MON COMMERCE') }}</span><h1>{{ title }}<span class="heading-period">.</span></h1><p>{{ config.sub }}</p></div><button v-if="canAdd" class="button primary" @click="openCreate"><ArrowDownToLine v-if="section==='reports'" :size="17"/><Plus v-else :size="17"/>{{ config.label }}</button></div>
  <div v-if="error" class="notice notice-error"><CircleAlert :size="17"/><span>{{ t(error) }}</span><button class="notice-close" @click="error=''" :aria-label="t('Fermer')"><X :size="16"/></button></div>
  <div v-if="success" class="notice notice-success"><BadgeCheck :size="17"/><span>{{ t(success) }}</span><button class="notice-close" @click="success=''" :aria-label="t('Fermer')"><X :size="16"/></button></div>
  <section v-if="visibleQueuedOperations.length" class="panel offline-queue-panel">
    <div class="panel-heading"><div><span class="eyebrow">{{ t('SYNCHRONISATION') }}</span><h2>{{ t('Opérations en attente') }} · {{ visibleQueuedOperations.length }}</h2></div><button v-if="isOnline" class="button secondary" @click="syncQueue">{{ t('Synchroniser') }}</button></div>
    <div v-for="operation in visibleQueuedOperations" :key="operation.id" class="queue-row">
      <div><strong>{{ operationLabel(operation) }}</strong><span>{{ operation.error || (operation.state==='conflict'?t('Conflit à résoudre'):t('En attente du réseau')) }}</span></div>
      <div class="queue-actions">
        <button v-if="operation.kind==='purchase_create'&&operation.state!=='conflict'&&['owner','manager','stock_manager'].includes(role)" class="small-action" :disabled="visibleQueuedOperations.some(item=>item.kind==='purchase_receive'&&item.dependsOn===operation.id)" @click="receiveQueuedPurchase(operation)">{{ t('Réceptionner après création') }}</button>
        <button v-if="operation.state==='conflict'&&isOnline" class="small-action" @click="retryOperation(operation)">{{ t('Réessayer') }}</button>
        <button v-if="operation.state!=='done'" class="small-action danger-action" @click="discardOperation(operation)">{{ t('Retirer') }}</button>
      </div>
    </div>
  </section>
  <template v-if="section==='reports'">
    <section class="filter-bar report-filters"><div class="date-filter"><label>{{ t('Du') }} <input v-model="dateFrom" type="date" /></label><label>{{ t('Au') }} <input v-model="dateTo" type="date" /></label></div><span class="filter-hint">{{ t('Période maximale : 366 jours') }}</span></section>
    <div v-if="report" class="metric-grid report-metrics"><article class="metric-card"><div class="metric-top"><span>{{ t('Chiffre d’affaires net') }}</span><span class="metric-icon icon-soft-green"><TrendingUp :size="18"/></span></div><strong>{{ money(report.summary.net_amount) }}</strong><div class="metric-bottom"><span class="metric-caption">{{ report.summary.sales_count }} {{ t('ventes validées') }}</span></div></article><article class="metric-card"><div class="metric-top"><span>{{ t('Montant brut') }}</span></div><strong>{{ money(report.summary.gross_amount) }}</strong><div class="metric-bottom"><span class="metric-caption">{{ t('Avant remises') }}</span></div></article><article class="metric-card"><div class="metric-top"><span>{{ t('Marge estimée') }}</span></div><strong>{{ money(report.summary.estimated_margin) }}</strong><div class="metric-bottom"><span class="metric-caption">{{ t(report.summary.margin_reliable?'Coûts renseignés':'Coûts à compléter') }}</span></div></article><article class="metric-card"><div class="metric-top"><span>{{ t('Remises accordées') }}</span></div><strong>{{ money(report.summary.discount_amount) }}</strong><div class="metric-bottom"><span class="metric-caption">{{ report.summary.items_without_cost }} {{ t('article(s) sans coût') }}</span></div></article></div>
    <section class="dashboard-grid report-grid"><article class="panel"><div class="panel-heading"><div><span class="eyebrow">{{ t('PERFORMANCE') }}</span><h2>{{ t('Produits les plus vendus') }}</h2></div><span class="period-pill">{{ dateFrom }} — {{ dateTo }}</span></div><div v-if="report?.top_products?.length" class="product-ranking"><div v-for="(p,i) in report.top_products" :key="p.product_id" class="rank-row"><span class="rank-index">0{{ Number(i)+1 }}</span><div class="rank-info"><strong>{{ p.name }}</strong><span>{{ p.sku }}</span></div><div class="rank-total"><strong>{{ money(p.amount) }}</strong><span>{{ num(p.quantity) }} {{ t('vendus') }}</span></div></div></div><div v-else class="empty-state compact"><div class="empty-icon"><Sparkles :size="20"/></div><strong>{{ t('Aucune vente sur cette période') }}</strong></div></article><article class="panel"><div class="panel-heading"><div><span class="eyebrow">{{ t('À SURVEILLER') }}</span><h2>{{ t('Stock faible') }}</h2></div><span class="alert-count">{{ lowStock.length }}</span></div><div v-if="lowStock.length" class="low-stock-list"><div v-for="item in lowStock.slice(0,6)" :key="item.id" class="low-stock-row"><div><strong>{{ item.name }}</strong><span>{{ item.sku }} · {{ t('seuil') }} {{ num(item.min_stock) }}</span></div><span class="stock-badge danger">{{ num(item.stock_quantity) }}</span></div></div><div v-else class="empty-state compact"><div class="empty-icon"><BadgeCheck :size="20"/></div><strong>{{ t('Tout est en ordre') }}</strong><span>{{ t('Aucun produit sous son seuil d’alerte.') }}</span></div></article></section>
  </template>
  <template v-else>
    <section class="filter-bar"><div class="search-field"><Search :size="17"/><input v-model="search" :placeholder="config.search" /></div><button class="filter-button" @click="load"><SlidersHorizontal :size="16"/> {{ t('Actualiser') }}</button><span class="result-count">{{ filteredRows.length }} {{ t(filteredRows.length===1?'résultat':'résultats') }}</span></section>
    <section v-if="busy" class="table-panel"><div class="loading-row"><LoaderCircle class="spin" :size="19"/>{{ t('Chargement de vos données…') }}</div></section>
    <section v-else-if="filteredRows.length" class="table-panel"><div class="table-scroll"><table><thead><tr>
      <template v-if="section==='products'"><th>{{ t('PRODUIT') }}</th><th>{{ t('RÉFÉRENCE') }}</th><th>{{ t('CATÉGORIE') }}</th><th>{{ t('PRIX DE VENTE') }}</th><th v-if="role!=='seller'">{{ t('EN STOCK') }}</th><th>{{ t('ÉTAT') }}</th><th></th></template>
      <template v-else-if="section==='categories'"><th>{{ t('CATÉGORIE') }}</th><th>{{ t('CATÉGORIE PARENTE') }}</th><th></th></template>
      <template v-else-if="section==='stock'"><th>{{ t('PRODUIT') }}</th><th>{{ t('MOUVEMENT') }}</th><th>{{ t('AVANT') }}</th><th>{{ t('VARIATION') }}</th><th>{{ t('APRÈS') }}</th><th>{{ t('DATE') }}</th><th>{{ t('MOTIF') }}</th></template>
      <template v-else-if="section==='sales'"><th>{{ t('TICKET') }}</th><th>{{ t('DATE') }}</th><th>{{ t('VENDEUR') }}</th><th>{{ t('ARTICLES') }}</th><th>{{ t('TOTAL') }}</th><th>{{ t('ÉTAT') }}</th><th></th></template>
      <template v-else-if="section==='purchases'"><th>{{ t('RÉFÉRENCE') }}</th><th>{{ t('FOURNISSEUR') }}</th><th>{{ t('DATE') }}</th><th>{{ t('ARTICLES') }}</th><th>{{ t('TOTAL') }}</th><th>{{ t('ÉTAT') }}</th><th></th></template>
      <template v-else-if="section==='suppliers'"><th>{{ t('FOURNISSEUR') }}</th><th>{{ t('TÉLÉPHONE') }}</th><th>{{ t('E-MAIL') }}</th><th>{{ t('ADRESSE') }}</th><th>{{ t('ÉTAT') }}</th><th></th></template>
      <template v-else-if="section==='team'"><th>{{ t('MEMBRE') }}</th><th>{{ t('E-MAIL') }}</th><th>{{ t('RÔLE') }}</th><th>{{ t('STATUT') }}</th><th></th></template>
      <template v-else><th>{{ t('PRODUIT') }}</th><th>{{ t('RÉFÉRENCE') }}</th><th>{{ t('QUANTITÉ VENDUE') }}</th><th>{{ t('CHIFFRE D’AFFAIRES') }}</th></template>
    </tr></thead><tbody>
      <tr v-for="row in filteredRows" :key="row.id">
        <template v-if="section==='products'"><td><div class="cell-title"><span class="product-thumb"><Package :size="17"/></span><span><strong>{{ row.name }}</strong><small>{{ row.brand||'—' }}</small></span></div></td><td><span class="mono-tag">{{ row.sku }}</span></td><td>{{ categories.find(c=>c.id===row.category)?.name||t('Sans catégorie') }}</td><td class="number-cell">{{ money(row.selling_price) }}</td><td v-if="role!=='seller'"><span class="stock-pill" :class="Number(row.stock_quantity)<=Number(row.min_stock)?'stock-low':''">{{ num(row.stock_quantity) }} <small>{{ unitName(row.unit) }}</small></span></td><td><span class="status-pill" :class="row.is_active?'status-green':'status-amber'">{{ row.is_active?t('Actif'):t('Désactivé') }}</span></td><td class="actions-cell"><button v-if="canManage" class="small-action" @click="editProduct(row)"><Pencil :size="12"/> {{ t('Modifier') }}</button><button v-if="canManage" class="small-action danger-action" @click="toggleProduct(row)">{{ t(row.is_active?'Désactiver':'Réactiver') }}</button></td></template>
        <template v-else-if="section==='categories'"><td><strong>{{ row.name }}</strong></td><td>{{ categories.find(c=>c.id===row.parent)?.name||'—' }}</td><td class="actions-cell"><button v-if="canManage" class="small-action" @click="editCategory(row)"><Pencil :size="12"/> {{ t('Modifier') }}</button></td></template>
        <template v-else-if="section==='stock'"><td><div class="cell-title"><span class="product-thumb"><Package :size="17"/></span><span><strong>{{ row.product_name }}</strong><small>{{ row.product_sku }}</small></span></div></td><td><span class="status-pill" :class="Number(row.quantity_delta)>0?'status-green':'status-amber'">{{ statusName(row.movement_type) }}</span></td><td>{{ num(row.quantity_before) }}</td><td class="number-cell" :class="Number(row.quantity_delta)>0?'positive-text':'negative-text'">{{ Number(row.quantity_delta)>0?'+':'' }}{{ num(row.quantity_delta) }}</td><td>{{ num(row.quantity_after) }}</td><td>{{ fmtDate(row.created_at) }}</td><td class="muted-cell">{{ row.reason||'—' }}</td></template>
        <template v-else-if="section==='sales'"><td><span class="ticket-cell">{{ row.number }}</span></td><td>{{ fmtDate(row.created_at) }}</td><td>{{ row.sold_by_email||'—' }}</td><td>{{ row.items?.length||0 }} {{ t(row.items?.length===1?'article':'articles') }}</td><td class="number-cell">{{ money(row.total_amount) }}</td><td><span class="status-pill" :class="statusClass(row.status)">{{ statusName(row.status) }}</span></td><td class="actions-cell"><button v-if="['owner','manager'].includes(role)&&row.status==='completed'" class="small-action danger-action" @click="cancelSale(row)">{{ t('Annuler') }}</button></td></template>
        <template v-else-if="section==='purchases'"><td><span class="ticket-cell">{{ row.reference }}</span></td><td>{{ row.supplier_name }}</td><td>{{ fmtDate(row.created_at) }}</td><td>{{ row.items?.length||0 }} {{ t(row.items?.length===1?'produit':'produits') }}</td><td class="number-cell">{{ money(row.total_amount) }}</td><td><span class="status-pill" :class="statusClass(row.status)">{{ statusName(row.status) }}</span></td><td class="actions-cell"><button v-if="isOnline&&['draft','ordered'].includes(row.status)&&['owner','manager','stock_manager'].includes(role)" class="small-action" @click="receivePurchase(row)">{{ t('Réceptionner') }}</button><button v-if="isOnline&&['draft','ordered'].includes(row.status)&&['owner','manager','stock_manager'].includes(role)" class="small-action danger-action" @click="cancelPurchase(row)">{{ t('Annuler') }}</button></td></template>
        <template v-else-if="section==='suppliers'"><td><div class="cell-title"><span class="vendor-avatar">{{ String(row.name||'?').slice(0,1).toUpperCase() }}</span><strong>{{ row.name }}</strong></div></td><td>{{ row.phone||'—' }}</td><td>{{ row.email||'—' }}</td><td class="muted-cell">{{ row.address||'—' }}</td><td><span class="status-pill" :class="row.is_active?'status-green':'status-amber'">{{ row.is_active?t('Actif'):t('Désactivé') }}</span></td><td class="actions-cell"><button v-if="canManage" class="small-action" @click="editSupplier(row)"><Pencil :size="12"/> {{ t('Modifier') }}</button><button v-if="canManage&&row.is_active" class="small-action danger-action" @click="deactivateSupplier(row)">{{ t('Désactiver') }}</button></td></template>
        <template v-else-if="section==='team'"><td><div class="cell-title"><span class="vendor-avatar">{{ String(row.username||row.email||'?').slice(0,1).toUpperCase() }}</span><strong>{{ row.username }}</strong></div></td><td>{{ row.email }}</td><td><span class="role-pill">{{ statusName(row.role) }}</span></td><td><span class="status-pill" :class="row.is_active?'status-green':'status-amber'">{{ row.is_active?t('Actif'):t('Suspendu') }}</span></td><td class="actions-cell"><button v-if="canManage&&role==='owner'&&row.email!==session.user?.email" class="small-action" @click="toggleMember(row)">{{ t(row.is_active?'Suspendre':'Réactiver') }}</button></td></template>
        <template v-else><td><strong>{{ row.name }}</strong></td><td><span class="mono-tag">{{ row.sku }}</span></td><td>{{ num(row.quantity) }}</td><td class="number-cell">{{ money(row.amount) }}</td></template>
      </tr>
    </tbody></table></div></section>
    <section v-else-if="!busy" class="empty-panel table-empty"><div class="empty-icon"><component :is="config.icon" :size="22"/></div><h3>{{ t(search?'Aucun résultat trouvé.':'La liste est encore vide.') }}</h3><p>{{ t(search?'Essayez un autre nom ou une autre référence.':'Les données de votre commerce apparaîtront ici dès leur création.') }}</p><button v-if="canAdd&&!search" class="button primary" @click="openCreate"><Plus :size="16"/>{{ config.label }}</button></section>
  </template>

  <div v-if="modal" class="modal-backdrop" @click.self="modal=false"><section class="modal-card"><div class="modal-heading"><div><span class="eyebrow">{{ session.shop?.name }}</span><h2>{{ t(editing ? 'Modifier' : config.label) }}</h2></div><button class="icon-button" :aria-label="t('Fermer')" @click="modal=false"><X :size="19"/></button></div><form class="modal-form" @submit.prevent="save">
    <template v-if="action==='products'"><label>{{ t('Nom du produit') }}<input v-model="form.name" required maxlength="200" placeholder="ex. Ciment 50 kg"/></label><div class="form-row"><label>{{ t('Référence SKU') }}<input v-model="form.sku" required maxlength="80" placeholder="CIM-050"/></label><label>{{ t('Marque') }}<input v-model="form.brand" :placeholder="t('Marque')"/></label></div><div class="form-row"><label>{{ t('Prix de vente') }}<input v-model="form.selling_price" type="number" min="0" step="0.01" required/></label><label v-if="role!=='seller'">{{ t('Prix d’achat') }}<input v-model="form.cost_price" type="number" min="0" step="0.01"/></label></div><div class="form-row"><label>{{ t('Unité') }}<select v-model="form.unit"><option value="piece">{{ t('Pièce') }}</option><option value="box">{{ t('Boîte') }}</option><option value="pack">{{ t('Paquet') }}</option><option value="meter">{{ t('Mètre') }}</option><option value="roll">{{ t('Rouleau') }}</option><option value="liter">{{ t('Litre') }}</option><option value="kg">{{ t('Kilogramme') }}</option></select></label><label>{{ t('Seuil d’alerte') }}<input v-model="form.min_stock" type="number" min="0" step="0.001"/></label></div><label>{{ t('Catégorie') }}<select v-model="form.category"><option value="">{{ t('Sans catégorie') }}</option><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></label></template>
    <template v-else-if="action==='categories'"><label>{{ t('Nom de la catégorie') }}<input v-model="form.name" required maxlength="120" placeholder="ex. Matériaux"/></label><label>{{ t('Catégorie parente') }}<select v-model="form.parent"><option value="">{{ t('Aucune') }}</option><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></label></template>
    <template v-else-if="action==='suppliers'"><label>{{ t('Nom du fournisseur') }}<input v-model="form.name" required :placeholder="t('Nom de l’entreprise')"/></label><div class="form-row"><label>{{ t('Téléphone') }}<input v-model="form.phone" type="tel" placeholder="+225 …"/></label><label>{{ t('E-mail') }}<input v-model="form.email" type="email" placeholder="contact@…"/></label></div><label>{{ t('Adresse') }}<input v-model="form.address" :placeholder="t('Adresse du fournisseur')"/></label><label>{{ t('Notes') }}<textarea v-model="form.notes" rows="2" :placeholder="t('Informations complémentaires')"/></label></template>
    <template v-else-if="action==='stock'"><label>{{ t('Produit') }}<select v-model="form.product_id" required><option value="" disabled>{{ t('Choisir un produit') }}</option><option v-for="p in products" :key="p.id" :value="p.id">{{ p.sku }} — {{ p.name }} ({{ num(p.stock_quantity) }} {{ unitName(p.unit) }})</option></select></label><div class="form-row"><label>{{ t('Variation de quantité') }}<input v-model="form.quantity_delta" type="number" step="0.001" required placeholder="ex. 5 ou -2"/></label><label>{{ t('Type') }}<select v-model="form.movement_type"><option value="adjustment">{{ t('Ajustement') }}</option><option value="loss">{{ t('Perte') }}</option></select></label></div><label>{{ t('Motif (minimum 3 caractères)') }}<input v-model="form.reason" required minlength="3" placeholder="Comptage physique, casse…"/></label><p class="form-hint">{{ t('Une quantité positive ajoute au stock; une quantité négative le réduit.') }}</p></template>
    <template v-else-if="action==='sales'"><div v-for="(item,index) in form.items" :key="index" class="sale-line-form"><label>{{ t('Produit') }}<select v-model="item.product_id" required><option value="" disabled>{{ t('Choisir un produit') }}</option><option v-for="p in products.filter(p=>p.is_active)" :key="p.id" :value="p.id">{{ p.name }} · {{ money(p.selling_price) }}<template v-if="role!=='seller'"> · {{ t('stock') }} {{ num(p.stock_quantity) }}</template></option></select></label><label>{{ t('Quantité') }}<input v-model="item.quantity" type="number" min="0.001" step="0.001" required/></label><button v-if="form.items.length>1" type="button" class="icon-button" :aria-label="t('Retirer cet article')" @click="removeSaleItem(index)"><X :size="16"/></button></div><button type="button" class="button secondary sale-add-item" @click="addSaleItem"><Plus :size="15"/> {{ t('Ajouter un article') }}</button><div class="form-row"><span></span><label v-if="['owner','manager'].includes(role)">{{ t('Remise') }} ({{ currency }})<input v-model="form.discount_amount" type="number" min="0" step="1"/></label></div><div class="sale-total"><span>{{ t('Total estimé') }}</span><strong>{{ money(estimatedSaleTotal) }}</strong></div><p class="form-hint">{{ t('Le prix appliqué est recalculé et confirmé par le serveur.') }}</p></template>
    <template v-else-if="action==='purchases'"><label>{{ t('Fournisseur') }}<select v-model="form.supplier_id" required><option value="" disabled>{{ t('Choisir un fournisseur') }}</option><option v-for="s in suppliers.filter(s=>s.is_active)" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label>{{ t('Produit') }}<select v-model="form.product_id" required><option value="" disabled>{{ t('Choisir un produit') }}</option><option v-for="p in products.filter(p=>p.is_active)" :key="p.id" :value="p.id">{{ p.sku }} — {{ p.name }}</option></select></label><div class="form-row"><label>{{ t('Quantité commandée') }}<input v-model="form.quantity_ordered" type="number" min="0.001" step="0.001" required/></label><label>{{ t('Coût unitaire') }}<input v-model="form.unit_cost" type="number" min="0" step="0.01" required/></label></div><label>{{ t('Notes') }}<textarea v-model="form.notes" rows="2" :placeholder="t('Détails de la commande')"/></label></template>
    <template v-else-if="action==='team'"><label>{{ t('Adresse e-mail') }}<input v-model="form.email" type="email" required placeholder="membre@exemple.com"/></label><label>{{ t('Nom d’utilisateur') }}<input v-model="form.username" required placeholder="mariam.kone"/></label><label>{{ t('Mot de passe temporaire') }}<input v-model="form.password" type="password" minlength="8" required :placeholder="t('8 caractères minimum')"/></label><label>{{ t('Rôle') }}<select v-model="form.role"><option value="manager">{{ t('Gérant·e') }}</option><option value="stock_manager">{{ t('Gestion de stock') }}</option><option value="seller">{{ t('Vendeur·se') }}</option><option value="viewer">{{ t('Lecture seule') }}</option></select></label><p class="form-hint">{{ t('Le nouveau membre recevra un compte à ces identifiants.') }}</p></template>
    <p v-if="error" class="form-error">{{ t(error) }}</p><div class="modal-actions"><button type="button" class="button secondary" @click="modal=false">{{ t('Annuler') }}</button><button type="submit" class="button primary" :disabled="pending"><LoaderCircle v-if="pending" class="spin" :size="16"/><Plus v-else :size="16"/>{{ pending?t('Enregistrement…'):t('Confirmer') }}</button></div>
  </form></section></div>
</template>
